class TestTallyImportSurvivesAPerVoucherFailure(FinanceTestCommon):
    def test_unbalanced_voucher_becomes_exception_not_a_crash(self):
        # Reproduces a real failure hit against an actual client export
        # (8127 real vouchers): one unbalanced entry used to raise
        # UserError out of account.move.create() itself, uncaught by the
        # try/except that only wrapped action_post() - crashing the whole
        # batch instead of logging just that one voucher, and (without a
        # savepoint) leaving the cursor's transaction aborted so every
        # subsequent voucher - even valid ones - would fail too.
        cash = self.env["account.account"].search(
            [("company_ids", "in", self.company.id), ("account_type", "=", "asset_cash")],
            limit=1,
        )
        income = self.env["account.account"].search(
            [("company_ids", "in", self.company.id), ("account_type", "=", "income")],
            limit=1,
        )
        self.assertTrue(cash and income, "test CoA must have cash/income accounts")

        xml_text = UNBALANCED_VOUCHER_AMONG_VALID_ONES.format(
            cash=cash.name, income=income.name
        )
        import_batch = self.env["bpro.tally.import.batch"].create(
            {
                "xml_file": base64.b64encode(xml_text.encode("utf-8")),
                "xml_filename": "unbalanced_fixture.xml",
            }
        )
        import_batch.action_import()

        self.assertEqual(import_batch.state, "done")
        self.assertEqual(
            import_batch.imported_count,
            1,
            "the valid voucher after the bad one must still import - the "
            "batch must not abort or silently drop it",
        )
        self.assertEqual(len(import_batch.exception_ids), 1)
        self.assertEqual(
            import_batch.exception_ids.voucher_number, "TALLY-UNBALANCED-001"
        )

        posted = self.env["account.move"].search(
            [("ref", "=", "TALLY-VALID-AFTER-001")]
        )
        self.assertEqual(posted.state, "posted")
        broken = self.env["account.move"].search(
            [("ref", "=", "TALLY-UNBALANCED-001")]
        )
        self.assertFalse(
            broken, "the failed voucher must not leave a half-created draft move behind"
        )


class TestTallyImportHandAuthoredFixture(FinanceTestCommon):
    def test_valid_voucher_imports_unmapped_ledger_becomes_exception(self):
        income_account = self.env["account.account"].search(
            [
                ("company_ids", "in", self.company.id),
                ("account_type", "=", "income"),
            ],
            limit=1,
        )
        expense_account = self.env["account.account"].search(
            [
                ("company_ids", "in", self.company.id),
                ("account_type", "=", "expense"),
            ],
            limit=1,
        )
        self.assertTrue(income_account and expense_account, "test CoA must have income/expense accounts")

        xml_content = HAND_AUTHORED_TALLY_XML.format(
            customer=self.customer.name,
            income_account=income_account.name,
            expense_account=expense_account.name,
        )
        import_batch = self.env["bpro.tally.import.batch"].create(
            {
                "xml_file": base64.b64encode(xml_content.encode("utf-8")),
                "xml_filename": "hand_authored_fixture.xml",
            }
        )
        import_batch.action_import()

        self.assertEqual(
            import_batch.imported_count,
            1,
            "the Sales voucher (known customer + known income ledger) must import",
        )
        self.assertEqual(len(import_batch.exception_ids), 1)
        self.assertIn(
            "Some Vendor Not In Odoo", import_batch.exception_ids.reason
        )

        posted = self.env["account.move"].search(
            [("ref", "=", "TALLY-INV-001")]
        )
        self.assertEqual(posted.state, "posted")
        # imported as a generic journal entry (move_type='entry'), so check
        # the actual debit total rather than amount_total, which is
        # computed for invoice-type moves, not plain journal entries
        self.assertEqual(sum(posted.line_ids.mapped("debit")), 5000.0)


# A real client Day Book export (Payment voucher type) signs the debit
# line's AMOUNT itself as negative, even though ISDEEMEDPOSITIVE="Yes"
# already marks it as a debit - discovered only once enough ledgers were
# mapped for these vouchers to reach the balance check at all; every
# Payment voucher in that ~8000-voucher file hit this same pattern.
NEGATIVE_SIGNED_PAYMENT_VOUCHER = """<?xml version="1.0" encoding="UTF-8"?>
<ENVELOPE>
  <HEADER>
    <TALLYREQUEST>Import Data</TALLYREQUEST>
  </HEADER>
  <BODY>
    <IMPORTDATA>
      <REQUESTDESC>
        <REPORTNAME>Vouchers</REPORTNAME>
      </REQUESTDESC>
      <REQUESTDATA>
        <TALLYMESSAGE xmlns:UDF="TallyUDF">
          <VOUCHER VCHTYPE="Payment" ACTION="Create">
            <DATE>20260615</DATE>
            <VOUCHERTYPENAME>Payment</VOUCHERTYPENAME>
            <VOUCHERNUMBER>1</VOUCHERNUMBER>
            <ALLLEDGERENTRIES.LIST>
              <LEDGERNAME>{expense_account}</LEDGERNAME>
              <ISDEEMEDPOSITIVE>Yes</ISDEEMEDPOSITIVE>
              <AMOUNT>-100.00</AMOUNT>
            </ALLLEDGERENTRIES.LIST>
            <ALLLEDGERENTRIES.LIST>
              <LEDGERNAME>{cash_account}</LEDGERNAME>
              <ISDEEMEDPOSITIVE>No</ISDEEMEDPOSITIVE>
              <AMOUNT>100.00</AMOUNT>
            </ALLLEDGERENTRIES.LIST>
          </VOUCHER>
        </TALLYMESSAGE>
      </REQUESTDATA>
    </IMPORTDATA>
  </BODY>
</ENVELOPE>
"""


class TestTallyImportHandlesNegativeSignedAmounts(FinanceTestCommon):
    def test_payment_voucher_with_negative_debit_amount_still_balances(self):
        expense_account = self.env["account.account"].search(
            [
                ("company_ids", "in", self.company.id),
                ("account_type", "=", "expense"),
            ],
            limit=1,
        )
        cash_account = self.env["account.account"].search(
            [
                ("company_ids", "in", self.company.id),
                ("account_type", "=", "asset_cash"),
            ],
            limit=1,
        )
        self.assertTrue(expense_account and cash_account, "test CoA must have expense/cash accounts")

        xml_content = NEGATIVE_SIGNED_PAYMENT_VOUCHER.format(
            expense_account=expense_account.name,
            cash_account=cash_account.name,
        )
        import_batch = self.env["bpro.tally.import.batch"].create(
            {
                "xml_file": base64.b64encode(xml_content.encode("utf-8")),
                "xml_filename": "negative_signed_payment.xml",
            }
        )
        import_batch.action_import()

        self.assertEqual(
            import_batch.imported_count,
            1,
            "a debit amount signed negative in the source XML must still balance and post",
        )
        self.assertFalse(import_batch.exception_ids)

        posted = self.env["account.move"].search([("ref", "=", "1")])
        self.assertEqual(posted.state, "posted")
        self.assertEqual(sum(posted.line_ids.mapped("debit")), 100.0)


# GST-enabled Sales/Purchase vouchers in Tally's "invoice mode" use a
# completely different layout from the plain-voucher-mode fixtures above:
# the party (and any tax) ledgers sit in LEDGERENTRIES.LIST while the
# stock item's own ledger side is only in ALLINVENTORYENTRIES.LIST under
# GSTLEDGERSOURCE - there is no ALLLEDGERENTRIES.LIST or LEDGERNAME at
# all for the item lines. Modeled on a real "GST SALES" voucher from this
# client's actual Day Book export (party debit split across a tax ledger
# and a sales ledger, verified to balance to the paisa against the source).
GST_INVOICE_MODE_SALES_VOUCHER = """<?xml version="1.0" encoding="UTF-8"?>
<ENVELOPE>
  <HEADER>
    <TALLYREQUEST>Import Data</TALLYREQUEST>
  </HEADER>
  <BODY>
    <IMPORTDATA>
      <REQUESTDESC>
        <REPORTNAME>Vouchers</REPORTNAME>
      </REQUESTDESC>
      <REQUESTDATA>
        <TALLYMESSAGE xmlns:UDF="TallyUDF">
          <VOUCHER VCHTYPE="GST SALES" ACTION="Create">
            <DATE>20260615</DATE>
            <VOUCHERTYPENAME>GST SALES</VOUCHERTYPENAME>
            <VOUCHERNUMBER>INV-001</VOUCHERNUMBER>
            <PARTYLEDGERNAME>{customer}</PARTYLEDGERNAME>
            <LEDGERENTRIES.LIST>
              <LEDGERNAME>{customer}</LEDGERNAME>
              <ISDEEMEDPOSITIVE>Yes</ISDEEMEDPOSITIVE>
              <ISPARTYLEDGER>Yes</ISPARTYLEDGER>
              <AMOUNT>-118.00</AMOUNT>
            </LEDGERENTRIES.LIST>
            <LEDGERENTRIES.LIST>
              <LEDGERNAME>{tax_account}</LEDGERNAME>
              <ISDEEMEDPOSITIVE>No</ISDEEMEDPOSITIVE>
              <ISPARTYLEDGER>No</ISPARTYLEDGER>
              <AMOUNT>18.00</AMOUNT>
            </LEDGERENTRIES.LIST>
            <ALLINVENTORYENTRIES.LIST>
              <STOCKITEMNAME>Test Stock Item</STOCKITEMNAME>
              <GSTSOURCETYPE>Ledger</GSTSOURCETYPE>
              <GSTLEDGERSOURCE>{income_account}</GSTLEDGERSOURCE>
              <ISDEEMEDPOSITIVE>No</ISDEEMEDPOSITIVE>
              <AMOUNT>100.00</AMOUNT>
            </ALLINVENTORYENTRIES.LIST>
          </VOUCHER>
        </TALLYMESSAGE>
      </REQUESTDATA>
    </IMPORTDATA>
  </BODY>
</ENVELOPE>
"""


class TestTallyImportHandlesInvoiceModeVouchers(FinanceTestCommon):
    def test_gst_sales_voucher_combines_ledgerentries_and_inventoryentries(self):
        tax_account = self.env["account.account"].search(
            [
                ("company_ids", "in", self.company.id),
                ("account_type", "=", "liability_current"),
            ],
            limit=1,
        )
        income_account = self.env["account.account"].search(
            [
                ("company_ids", "in", self.company.id),
                ("account_type", "=", "income"),
            ],
            limit=1,
        )
        self.assertTrue(tax_account and income_account, "test CoA must have liability/income accounts")

        xml_content = GST_INVOICE_MODE_SALES_VOUCHER.format(
            customer=self.customer.name,
            tax_account=tax_account.name,
            income_account=income_account.name,
        )
        import_batch = self.env["bpro.tally.import.batch"].create(
            {
                "xml_file": base64.b64encode(xml_content.encode("utf-8")),
                "xml_filename": "gst_invoice_mode.xml",
            }
        )
        import_batch.action_import()

        self.assertEqual(
            import_batch.imported_count,
            1,
            "an invoice-mode voucher (no ALLLEDGERENTRIES.LIST, ledger data "
            "split across LEDGERENTRIES.LIST and ALLINVENTORYENTRIES.LIST) "
            "must still import",
        )
        self.assertFalse(import_batch.exception_ids)

        posted = self.env["account.move"].search([("ref", "=", "INV-001")])
        self.assertEqual(posted.state, "posted")
        self.assertEqual(sum(posted.line_ids.mapped("debit")), 118.0)
        self.assertEqual(
            posted.line_ids.filtered(lambda l: l.account_id == income_account).credit,
            100.0,
        )
        self.assertEqual(
            posted.line_ids.filtered(lambda l: l.account_id == tax_account).credit,
            18.0,
        )
